const lesson8Data={"title":"你会做菜吗？","pinyin":"Nǐ huì zuò cài ma?","vi":"Bạn biết nấu ăn không?","rows":[["回","huí","về; trở về","我想回家吃饭。","Wǒ xiǎng huí jiā chī fàn.","Tôi muốn về nhà ăn cơm."],["会","huì","biết (kỹ năng đã học)","我会说汉语。","Wǒ huì shuō Hànyǔ.","Tôi biết nói tiếng Trung."],["做菜","zuò cài","nấu ăn","你会做菜吗？","Nǐ huì zuò cài ma?","Bạn biết nấu ăn không?"],["水果","shuǐguǒ","trái cây","我喜欢吃水果。","Wǒ xǐhuan chī shuǐguǒ.","Tôi thích ăn trái cây."],["沙拉","shālā","salad","我会做水果沙拉。","Wǒ huì zuò shuǐguǒ shālā.","Tôi biết làm salad trái cây."],["酒","jiǔ","rượu","他不会喝酒。","Tā bú huì hē jiǔ.","Anh ấy không biết uống rượu."],["瓶","píng","chai (lượng từ)","桌子上有两瓶红酒。","Zhuōzi shang yǒu liǎng píng hóngjiǔ.","Trên bàn có hai chai vang đỏ."],["哪里","nǎli","đâu có (đáp lời khen)","哪里哪里，你的汉语也很好。","Nǎli nǎli, nǐ de Hànyǔ yě hěn hǎo.","Đâu có đâu có, tiếng Trung của bạn cũng rất tốt."],["尝","cháng","nếm; thử món","请你尝一下这个菜。","Qǐng nǐ cháng yíxià zhège cài.","Mời bạn nếm thử món này."],["聪明","cōngming","thông minh","美京非常聪明。","Měijīng fēicháng cōngming.","Mỹ Kinh rất thông minh."],["外语","wàiyǔ","ngoại ngữ","你会说什么外语？","Nǐ huì shuō shénme wàiyǔ?","Bạn biết nói ngoại ngữ nào?"],["除了……以外","chúle…yǐwài","ngoài…ra","除了汉语以外，我还会说英语。","Chúle Hànyǔ yǐwài, wǒ hái huì shuō Yīngyǔ.","Ngoài tiếng Trung ra, tôi còn biết nói tiếng Anh."],["日语","Rìyǔ","tiếng Nhật","她会说日语。","Tā huì shuō Rìyǔ.","Cô ấy biết nói tiếng Nhật."],["真的","zhēn de","thật; thật sự","真的吗？你会做红酒？","Zhēn de ma? Nǐ huì zuò hóngjiǔ?","Thật sao? Bạn biết làm vang đỏ à?"],["好喝","hǎohē","ngon (đồ uống)","这个茶很好喝。","Zhège chá hěn hǎohē.","Trà này rất ngon."],["法语","Fǎyǔ","tiếng Pháp","除了英语以外，我还会说法语。","Chúle Yīngyǔ yǐwài, wǒ hái huì shuō Fǎyǔ.","Ngoài tiếng Anh, tôi còn biết nói tiếng Pháp."]],"aliases":{"回":["回来"]},"dialogues":[["01 · Mời bạn đến nhà ăn tối",[["田中","美京，今天你去哪儿吃晚饭？","Měijīng, jīntiān nǐ qù nǎr chī wǎnfàn?","Mỹ Kinh, tối nay bạn ăn cơm ở đâu?"],["美京","我想回家吃晚饭。","Wǒ xiǎng huí jiā chī wǎnfàn.","Tôi muốn về nhà ăn cơm tối."],["田中","你会做菜吗？","Nǐ huì zuò cài ma?","Bạn biết nấu ăn không?"],["美京","会，我会做韩国菜和中国菜。你呢？","Huì, wǒ huì zuò Hánguócài hé Zhōngguócài. Nǐ ne?","Có, tôi biết nấu món Hàn và món Trung. Còn bạn?"],["田中","你真行！我不会做菜，我只会吃。","Nǐ zhēn xíng! Wǒ bú huì zuò cài, wǒ zhǐ huì chī.","Bạn giỏi thật! Tôi không biết nấu, chỉ biết ăn thôi."],["美京","那你晚上来我家吃吧，我今天做韩国菜。","Nà nǐ wǎnshang lái wǒ jiā chī ba, wǒ jīntiān zuò Hánguócài.","Vậy tối nay đến nhà tôi ăn nhé, hôm nay tôi nấu món Hàn."],["田中","太好了！对了，我会做水果沙拉。晚上，我做一个吧！","Tài hǎo le! Duìle, wǒ huì zuò shuǐguǒ shālā. Wǎnshang, wǒ zuò yí ge ba!","Tốt quá! À, tôi biết làm salad trái cây. Tối nay để tôi làm một phần nhé!"],["美京","田中，你会喝酒吗？","Tiánzhōng, nǐ huì hē jiǔ ma?","Tanaka, bạn biết uống rượu không?"],["田中","会喝一点儿。你呢？","Huì hē yìdiǎnr. Nǐ ne?","Tôi uống được một chút. Còn bạn?"],["美京","我很喜欢喝红酒，我还会做红酒。上个月我做了两瓶红酒。","Wǒ hěn xǐhuan hē hóngjiǔ, wǒ hái huì zuò hóngjiǔ. Shàng ge yuè wǒ zuò le liǎng píng hóngjiǔ.","Tôi rất thích vang đỏ, còn biết làm vang nữa. Tháng trước tôi làm hai chai."],["田中","是吗？你真行！","Shì ma? Nǐ zhēn xíng!","Thế à? Bạn giỏi thật!"],["美京","哪里哪里！今天晚上尝一下吧！","Nǎli nǎli! Jīntiān wǎnshang cháng yíxià ba!","Đâu có đâu có! Tối nay nếm thử nhé!"],["田中","好的！","Hǎo de!","Được!"]]],["02 · Bạn biết những ngoại ngữ nào?",[["卡玛拉","田中，听美京说你很喜欢吃韩国菜？","Tiánzhōng, tīng Měijīng shuō nǐ hěn xǐhuan chī Hánguócài?","Tanaka, nghe Mỹ Kinh nói bạn rất thích ăn món Hàn?"],["田中","对，昨天美京做了韩国菜，请我吃了。","Duì, zuótiān Měijīng zuò le Hánguócài, qǐng wǒ chī le.","Đúng, hôm qua Mỹ Kinh nấu món Hàn và mời tôi ăn."],["卡玛拉","是吗？美京会做菜？","Shì ma? Měijīng huì zuò cài?","Thế à? Mỹ Kinh biết nấu ăn?"],["田中","对，除了做菜以外，她还会做红酒。真的很好喝！","Duì, chúle zuò cài yǐwài, tā hái huì zuò hóngjiǔ. Zhēn de hěn hǎohē!","Đúng, ngoài nấu ăn, cô ấy còn biết làm vang đỏ. Ngon thật!"],["卡玛拉","是吗？我觉得美京非常聪明，听说她会说很多外语，除了汉语以外，她还会说英语和日语。","Shì ma? Wǒ juéde Měijīng fēicháng cōngming, tīngshuō tā huì shuō hěn duō wàiyǔ, chúle Hànyǔ yǐwài, tā hái huì shuō Yīngyǔ hé Rìyǔ.","Thế à? Tôi thấy Mỹ Kinh rất thông minh, nghe nói cô ấy biết nhiều ngoại ngữ, ngoài tiếng Trung còn nói được tiếng Anh và tiếng Nhật."],["田中","真的吗？卡玛拉，你也很聪明啊，除了英语以外，你还会说汉语和法语。","Zhēn de ma? Kǎmǎlā, nǐ yě hěn cōngming a, chúle Yīngyǔ yǐwài, nǐ hái huì shuō Hànyǔ hé Fǎyǔ.","Thật sao? Kamala, bạn cũng thông minh mà, ngoài tiếng Anh còn biết tiếng Trung và tiếng Pháp."],["卡玛拉","哪里哪里！你的汉语非常好！","Nǎli nǎli! Nǐ de Hànyǔ fēicháng hǎo!","Đâu có đâu có! Tiếng Trung của bạn rất tốt!"],["田中","我只会说一点儿汉语。","Wǒ zhǐ huì shuō yìdiǎnr Hànyǔ.","Tôi chỉ nói được một chút tiếng Trung."],["卡玛拉","我也只会说一点儿汉语。","Wǒ yě zhǐ huì shuō yìdiǎnr Hànyǔ.","Tôi cũng chỉ nói được một chút tiếng Trung."]]]],"reading":"海伦昨天去美京家吃饭了。美京很会做菜，昨天做了三个韩国菜，都很好吃，海伦吃了很多。美京很聪明，除了会做菜以外，还会做红酒，去年做了两瓶红酒。海伦尝了一下，觉得非常好喝。她平时只喝一点儿酒，可是昨天喝了三大杯。美京和海伦每个星期一和星期三都一起去图书馆学习，除了学习以外，还常常一起玩儿。她们是好朋友。","exercises":{"vocab":[["他今年十六岁，不可以喝（　）。","酒","Chưa đủ tuổi, không được uống rượu."],["这个菜是我做的，请你（　）一下。","尝","尝一下 — nếm thử."],["A：你的汉语真好！ B：（　），我的汉语不好。","哪里哪里","Đáp lời khen bằng 哪里哪里."],["我爸爸每天晚上八点（　）家。","回","回家 — về nhà."],["我喜欢吃水果（　）。","沙拉","水果沙拉 — salad trái cây."]],"reading":[["美京很（　）做菜。","会","会 + động từ: biết làm."],["美京很（　），除了会做菜以外，还会做红酒。","聪明","聪明 — thông minh."],["她去年做了两（　）红酒。","瓶","瓶 là lượng từ cho chai."],["海伦觉得红酒非常（　）。","好喝","好喝 dùng cho đồ uống."]],"choose":[["我（　）借一下你的手机，好吗？（会／可以／想）","想","想 diễn tả mong muốn; 好吗 xin ý kiến."],["他（　）说很多外语。（会／想／要）","会","Kỹ năng đã học: 会."],["对不起，你（　）帮我一下吗？（会／可以／想／要）","可以","Xin phép/nhờ giúp: 可以."],["太累了，我（　）休息一下。（会／可以／要）","要","要 ở đây diễn tả ý định."]],"comprehension":[["谁平时只喝一点儿酒？",["美京和海伦","美京","海伦"],2],["谁会做菜？",["美京和海伦","美京","海伦"],1],["谁昨天在美京家吃了韩国菜？",["美京和海伦","美京","海伦"],2],["谁昨天喝了不少酒？",["美京和海伦","美京","海伦"],2],["谁会做红酒？",["美京和海伦","美京","海伦"],1],["谁一起去图书馆学习？",["美京和海伦","美京","海伦"],0]]}};
